mapper.select:
SELECT s.* FROM solution s
WHERE s.status = #{status}
AND s.deleted = 0

    AND s.difficulty = #{difficulty}


    AND EXISTS (
        SELECT 1 FROM solution_tag_rel rel
        WHERE rel.solution_id = s.id
        AND rel.tag_id = #{tagId}
        AND rel.deleted = 0
    )

ORDER BY s.view_count DESC, s.create_time DESC
